// Builds lib/admin/launch-kit.generated.ts from the markdown in docs/marketing/jp45/ (the launch kit JP posts and
// sends himself). The admin Plan tab shows it with Copy buttons; the markdown stays the source of truth.
//   node scripts/launch-kit-gen.mjs            write the generated file
//   node scripts/launch-kit-gen.mjs --check    exit 1 if the generated file is stale (the vitest guard uses this)
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const DOCS = path.resolve(here, '../../../docs/marketing/jp45');
const OUT = path.resolve(here, '../lib/admin/launch-kit.generated.ts');
const FILES = ['press-one-pager', 'press-list', 'press-emails', 'product-hunt', 'founder-posts', 'bios'];

export function parseDoc(md) {
  const lines = md.replace(/\r/g, '').split('\n');
  const title = (lines.find((l) => l.startsWith('# ')) ?? '# Untitled').slice(2).trim();
  const body = lines.slice(lines.findIndex((l) => l.startsWith('# ')) + 1).join('\n');
  const parts = body.split(/^## /m);
  const intro = parts[0].trim();
  const sections = parts.slice(1)
    .map((p) => { const nl = p.indexOf('\n'); return { heading: (nl < 0 ? p : p.slice(0, nl)).trim(), text: (nl < 0 ? '' : p.slice(nl + 1)).trim() }; })
    .filter((s) => s.text.length > 0);
  return { title, intro, sections };
}

export function build() {
  const docs = FILES.map((id) => {
    const md = readFileSync(path.join(DOCS, `${id}.md`), 'utf8');
    return { id, ...parseDoc(md), markdown: md.trim() };
  });
  const html = readFileSync(path.join(DOCS, 'press-one-pager.html'), 'utf8');
  return `// GENERATED by scripts/launch-kit-gen.mjs from docs/marketing/jp45/*.md. Do not edit by hand; edit the markdown and rerun.
export interface LaunchKitSection { heading: string; text: string }
export interface LaunchKitDocRaw { id: string; title: string; intro: string; sections: LaunchKitSection[]; markdown: string }

export const LAUNCH_KIT_RAW: readonly LaunchKitDocRaw[] = ${JSON.stringify(docs, null, 2)};

export const PRESS_ONE_PAGER_HTML = ${JSON.stringify(html)};
`;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const next = build();
  if (process.argv.includes('--check')) {
    const cur = existsSync(OUT) ? readFileSync(OUT, 'utf8') : '';
    if (cur !== next) { console.error('launch-kit.generated.ts is stale: run node scripts/launch-kit-gen.mjs'); process.exit(1); }
    console.log('launch kit generated file is current');
  } else {
    writeFileSync(OUT, next);
    console.log(`wrote ${path.relative(process.cwd(), OUT)}`);
  }
}
